import { Flow } from "flow-sdk";

export const breakdownScript = async (
  script: string,
  numCells: number,
  availableShotTypes: string[],
  availablePovs: string[]
): Promise<Array<{ prompt: string, shotType: string, pov: string }>> => {
  const { text } = await Flow.generate.text(`Break down the following script or story into a precise ${numCells}-panel storyboard. Focus on visually describing what should be seen in the scene. Make it evocative and detailed.

Script: ${script}`, {
    systemInstruction: `You are an expert storyboard artist. Respond ONLY with a valid JSON array of objects. Each object must have three string keys: "prompt" (detailed visual description), "shotType" (one of: ${availableShotTypes.join(', ')}), and "pov" (one of: ${availablePovs.join(', ')}). Do not include markdown code blocks.`,
    thinkingLevel: 'low'
  });

  try {
    const jsonStr = text.match(/\[[\s\S]*\]/)?.[0] || text;
    return JSON.parse(jsonStr);
  } catch (e) {
    console.error("Failed to parse JSON:", text);
    throw new Error("AI returned invalid breakdown format.");
  }
};

export const selectImageFile = async (): Promise<{ base64: string; mimeType: string } | null> => {
  try {
    const media = await Flow.media.select({ filter: 'image' });
    return { base64: media.base64, mimeType: media.mimeType };
  } catch (e) {
    return null; // user cancelled
  }
};

export const generateImage = async (
  prompt: string, 
  references: { base64: string, mimeType: string }[], 
  aspectRatio: string, 
  modelName: string
): Promise<{ base64: string; mimeType: string }> => {
  const referenceImageMediaIds: string[] = [];

  if (references && references.length > 0) {
    for (const ref of references) {
      // Use Flow.upload to get a mediaId without saving to the permanent gallery
      const { mediaId } = await Flow.upload({ 
        base64: ref.base64, 
        mimeType: ref.mimeType as any,
        name: 'Reference'
      });
      referenceImageMediaIds.push(mediaId);
    }
  }

  const result = await Flow.generate.image({
    prompt,
    modelDisplayName: modelName,
    aspectRatio: aspectRatio as any,
    ...(referenceImageMediaIds.length > 0 ? { referenceImageMediaIds } : {})
  });

  return {
    base64: result.base64,
    mimeType: result.mimeType
  };
};

export const refineImage = async (
  prompt: string,
  base64Src: string,
  mimeTypeSrc: string,
  aspectRatio: string,
  modelName: string,
  extraRefs?: { base64: string; mimeType: string }[]
): Promise<{ base64: string; mimeType: string }> => {
  const referenceImageMediaIds: string[] = [];

  // Base image goes first
  const { mediaId: baseId } = await Flow.upload({ 
    base64: base64Src, 
    mimeType: mimeTypeSrc as any,
    name: 'Refinement Base'
  });
  referenceImageMediaIds.push(baseId);

  if (extraRefs) {
    for (const ref of extraRefs) {
      const { mediaId } = await Flow.upload({ 
        base64: ref.base64, 
        mimeType: ref.mimeType as any,
        name: 'Extra Reference'
      });
      referenceImageMediaIds.push(mediaId);
    }
  }

  const result = await Flow.generate.image({
    prompt,
    modelDisplayName: modelName,
    aspectRatio: aspectRatio as any,
    referenceImageMediaIds
  });

  return {
    base64: result.base64,
    mimeType: result.mimeType
  };
};

export const upscaleImage = async (
  prompt: string,
  base64Src: string,
  mimeTypeSrc: string,
  aspectRatio: string,
  modelName: string,
  imageSize: string = "1K",
  extraRefs?: { base64: string, mimeType: string }[]
): Promise<{ base64: string; mimeType: string }> => {
  const referenceImageMediaIds: string[] = [];

  // Base image
  const { mediaId: baseId } = await Flow.upload({ 
    base64: base64Src, 
    mimeType: mimeTypeSrc as any,
    name: 'Upscale Base'
  });
  referenceImageMediaIds.push(baseId);

  if (extraRefs) {
    for (const ref of extraRefs) {
      const { mediaId } = await Flow.upload({ 
        base64: ref.base64, 
        mimeType: ref.mimeType as any,
        name: 'Extra Reference'
      });
      referenceImageMediaIds.push(mediaId);
    }
  }

  const result = await Flow.generate.image({
    prompt,
    modelDisplayName: modelName,
    aspectRatio: aspectRatio as any,
    referenceImageMediaIds
  });

  return {
    base64: result.base64,
    mimeType: result.mimeType
  };
};

export type GridLayout = '2x2' | '3x3' | '1x4' | 'custom';
export type AspectRatio = '1:1' | '16:9' | '9:16' | '4:3' | '3:4';

export interface GridCell {
  id: string;
  prompt: string;
  refinementPrompt?: string;
  shotType: string;
  pov: string;
  sketchMediaId?: string;
  sketchBase64?: string;
  sketchMimeType?: string;
  localRefs?: { id: string, base64: string, mimeType: string }[];
  result?: {
    mediaId?: string;
    base64: string;
    mimeType: string;
  };
  expandedResult?: {
    mediaId?: string;
    base64: string;
    mimeType: string;
  };
  isModified?: boolean;
  isRefined?: boolean;
}

export interface CustomStyle {
  id: string;
  name: string;
  prompt: string;
}

export interface GridSession {
  id: string;
  timestamp: number;
  layout: GridLayout;
  rows: number;
  cols: number;
  aspectRatio: AspectRatio;
  prevAspectRatio?: AspectRatio;
  cells: GridCell[];
  globalPrompt: string;
  useGlobalPrompt: boolean;
  scriptMode?: boolean;
  scriptContent?: string;
  selectedStyle: string;
  customStyles: CustomStyle[];
  model: string;
  globalRefs: {
    images: {id: string, base64: string, mimeType: string}[];
  };
  masterGridResult?: {
    base64: string;
    mimeType: string;
  };
}

import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown } from 'lucide-react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-1 mb-1.5 mt-1">
    <span className="text-[9px] font-bold text-gray-400 tracking-widest uppercase">{children}</span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; onClick?: () => void; disabled?: boolean;
  className?: string;
}> = ({ icon, children, variant = 'filled', onClick, disabled, className = '' }) => {
  const base = 'flex flex-row flex-nowrap items-center gap-2 justify-center rounded-xl font-bold tracking-tight transition-all cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed select-none duration-200 overflow-visible whitespace-nowrap';
  const variants: Record<string, string> = {
    filled: 'bg-neutral-800 hover:bg-neutral-700 text-white text-[10px] h-[38px] px-4',
    outline: 'bg-white/5 hover:bg-white/10 text-[10px] text-white border border-white/5 h-[38px] px-4',
    solid: 'bg-white hover:bg-gray-200 text-black text-[10px] h-[38px] px-4',
  };
  return (
    <button className={`${base} ${variants[variant]} ${className}`} onClick={onClick} disabled={disabled}>
      {icon && <div className="flex items-center justify-center w-4 h-4 shrink-0 pointer-events-none">{icon}</div>}
      <div className="uppercase flex flex-row flex-nowrap items-center gap-2 pointer-events-none">
        {children}
      </div>
    </button>
  );
};

export const FieldDropdown: React.FC<{
  label: string; value: string; options: string[];
  disabledOptions?: string[];
  onChange: (val: string) => void; className?: string;
}> = ({ label, value, options, disabledOptions = [], onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const l = (e: MouseEvent) => { if (!ref.current?.contains(e.target as Node)) setIsOpen(false); };
    document.addEventListener('mousedown', l);
    return () => document.removeEventListener('mousedown', l);
  }, []);

  return (
    <div ref={ref} className={'relative ' + className}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full h-[46px] text-left bg-white/5 hover:bg-white/10 transition-all rounded-xl flex flex-col gap-0.5 justify-center pl-3 pr-2 select-none focus:outline-none">
        <p className="text-[8px] font-bold text-gray-400 tracking-tighter uppercase">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white/80 truncate">{value}</span>
          <ChevronDown size={12} className="text-gray-500 transition-transform duration-200" style={{ transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)' }} />
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-[110] top-[calc(100%+4px)] left-0 w-full bg-neutral-900 rounded-xl overflow-hidden shadow-2xl border border-white/5 origin-top animate-dropdown">
          <div className="max-h-60 overflow-y-auto py-1 dark-scrollbar">
            {options.map((opt) => {
              const isDisabled = disabledOptions.includes(opt);
              return (
                <button 
                  key={opt} type="button" disabled={isDisabled}
                  className={'w-full text-left px-3 py-2 text-[10px] font-bold transition-colors ' + (isDisabled ? 'opacity-10 cursor-not-allowed text-white' : value === opt ? 'bg-white/10 text-white' : 'text-gray-200 hover:bg-white/5')}
                  onClick={() => { if(!isDisabled) { onChange(opt); setIsOpen(false); } }}>
                  {opt}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

