import React, { useState, useRef, useEffect } from 'react';

interface PromptTextareaProps {
  value: string;
  onChange: (val: string) => void;
  onKeyDown?: (e: React.KeyboardEvent<HTMLTextAreaElement>) => void;
  placeholder?: string;
  className?: string;
  localRefs?: { id: string, base64: string, mimeType: string, label?: string, display?: string }[];
}

export const PromptTextarea: React.FC<PromptTextareaProps> = ({ value, onChange, onKeyDown, placeholder, className, localRefs }) => {
  const [showAuto, setShowAuto] = useState(false);
  const [autoFilter, setAutoFilter] = useState('');
  const [autoIndex, setAutoIndex] = useState(0);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const refsList = localRefs?.map((r, i) => ({ ...r, label: r.label || `image${i + 1}`, display: r.display || `Image ${i + 1}` })) || [];
  const filteredList = refsList.filter(r => r.label.includes(autoFilter.toLowerCase()));

  useEffect(() => {
    if (!showAuto) {
      setAutoFilter('');
      setAutoIndex(0);
    }
  }, [showAuto]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (showAuto) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setAutoIndex(prev => (prev + 1) % filteredList.length);
        return;
      }
      if (e.key === 'ArrowUp') {
        e.preventDefault();
        setAutoIndex(prev => (prev - 1 + filteredList.length) % filteredList.length);
        return;
      }
      if (e.key === 'Enter' || e.key === 'Tab') {
        e.preventDefault();
        if (filteredList[autoIndex]) {
          insertRef(filteredList[autoIndex].label);
        }
        return;
      }
      if (e.key === 'Escape') {
        setShowAuto(false);
        return;
      }
    }

    if (onKeyDown) onKeyDown(e);
  };

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const val = e.target.value;
    onChange(val);

    const cursor = e.target.selectionStart;
    const textBeforeCursor = val.slice(0, cursor);
    const atMatch = textBeforeCursor.match(/@(\w*)$/);

    if (atMatch) {
      setShowAuto(true);
      setAutoFilter(atMatch[1]);
      setAutoIndex(0);
    } else {
      setShowAuto(false);
    }
  };

  const insertRef = (label: string) => {
    if (!textareaRef.current) return;
    const cursor = textareaRef.current.selectionStart;
    const textBeforeCursor = value.slice(0, cursor);
    const textAfterCursor = value.slice(cursor);

    const atMatch = textBeforeCursor.match(/@(\w*)$/);
    if (atMatch) {
      const beforeAt = textBeforeCursor.slice(0, atMatch.index);
      const newVal = beforeAt + '@' + label + ' ' + textAfterCursor;
      onChange(newVal);
      setShowAuto(false);

      // Try to set cursor after insert
      setTimeout(() => {
        if (textareaRef.current) {
          textareaRef.current.focus();
          const newPos = beforeAt.length + label.length + 2;
          textareaRef.current.setSelectionRange(newPos, newPos);
        }
      }, 0);
    }
  };

  return (
    <div className="relative w-full">
      <textarea
        ref={textareaRef}
        value={value}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        className={className}
      />
      {showAuto && filteredList.length > 0 && (
        <div className="absolute z-50 left-0 bottom-full mb-1 w-48 bg-neutral-900 border border-white/10 rounded-lg shadow-2xl overflow-hidden text-[10px]">
          <div className="p-1 px-2 text-[8px] uppercase tracking-wider text-gray-500 font-bold bg-white/5">Local References</div>
          {filteredList.map((ref, idx) => (
            <div 
              key={ref.id} 
              onClick={() => insertRef(ref.label)}
              className={`flex items-center gap-2 p-1.5 cursor-pointer transition-colors ${idx === autoIndex ? 'bg-white/10' : 'hover:bg-white/5'}`}
            >
              <img src={"data:" + ref.mimeType + ";base64," + ref.base64} className="w-6 h-6 object-cover rounded" />
              <div className="flex flex-col">
                <span className="text-white font-bold">@{ref.label}</span>
                <span className="text-gray-400 text-[8px]">{ref.display}</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { X, ChevronLeft, ChevronRight, Info } from 'lucide-react';
import { PillButton } from './Common';

const TUTORIAL_STEPS = [
  {
    title: "Welcome to Grid Architect",
    content: "This tool lets you build consistent storyboards and image grids perfectly seamlessly. Let's walk through the main features."
  },
  {
    title: "Grid Layout & Ratios",
    content: "Start by choosing your grid format (2x2, 3x3, 1x4, or custom). Then pick the overall aspect ratio. The generated frames will perfectly snap together."
  },
  {
    title: "Global vs Individual Prompts",
    content: "Toggle 'Use Global Prompt' to type one master prompt that drives the entire grid. Uncheck it to write unique prompts for every single frame."
  },
  {
    title: "Style Presets & Models",
    content: "Select a visual style (like Cyberpunk or Anime) and an AI model. This helps keep character design, lighting, and textures consistent across all your frames."
  },
  {
    title: "Composition References",
    content: "Click '+ COMPOSITION' on any frame to upload a structural sketch. The AI will strictly follow your sketch boundaries while painting entirely new details."
  },
  {
    title: "Refinement & Upscaling",
    content: "Once a grid is generated, click any frame to open the Refiner. Modify camera angles, write adjustments, or upscale individual panels to 1K resolution."
  },
  {
    title: "Multi-Selection",
    content: "Hold Shift + Click on frames in the grid to select multiple images. You can then download or enhance them all as a batch."
  }
];

export const TutorialOverlay = ({ onClose }: { onClose: () => void }) => {
  const [step, setStep] = useState(0);

  const handleNext = () => {
    if (step < TUTORIAL_STEPS.length - 1) setStep(s => s + 1);
    else onClose();
  }

  const handlePrev = () => {
    if (step > 0) setStep(s => s - 1);
  }

  return (
    <div className="fixed inset-0 z-[500] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
      <div className="bg-[#0f0f0f] border border-white/10 rounded-3xl w-full max-w-lg shadow-2xl flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-white/5">
          <div className="flex items-center gap-2 text-white/80">
            <Info size={18} className="text-blue-400" />
            <h2 className="text-sm font-bold tracking-widest uppercase">Quick Tutorial</h2>
          </div>
          <button onClick={onClose} className="p-2 text-gray-500 hover:text-white hover:bg-white/5 rounded-xl transition-all">
            <X size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="p-8 flex flex-col gap-4 min-h-[220px]">
          <h3 className="text-xl font-bold text-white tracking-tight">{TUTORIAL_STEPS[step].title}</h3>
          <p className="text-gray-400 text-sm leading-relaxed">{TUTORIAL_STEPS[step].content}</p>
        </div>

        {/* Footer / Controls */}
        <div className="p-6 bg-black/50 border-t border-white/5 flex items-center justify-between">
          <div className="text-[10px] font-bold text-white/30 uppercase tracking-widest">
            {step + 1} / {TUTORIAL_STEPS.length}
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={handlePrev}
              disabled={step === 0}
              className="p-3 text-white/50 hover:text-white hover:bg-white/10 rounded-xl transition-all disabled:opacity-30 disabled:hover:bg-transparent"
            >
              <ChevronLeft size={16} />
            </button>
            <PillButton variant={step === TUTORIAL_STEPS.length - 1 ? "solid" : "outline"} onClick={handleNext} className="gap-2 px-6 whitespace-nowrap min-w-max flex-shrink-0">
              {step === TUTORIAL_STEPS.length - 1 ? 'Get Started' : 'Next'}
              {step < TUTORIAL_STEPS.length - 1 && <ChevronRight size={14} />}
            </PillButton>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { X, Download, Maximize2, Loader2, Check, AlertCircle, ChevronLeft, ChevronRight, Sparkles, RefreshCw, Save, Plus } from 'lucide-react';
import { Flow } from 'flow-sdk';
import { PillButton, SectionLabel, FieldDropdown } from './Common';
import { AspectRatio, GridCell } from '../types';
import { ASPECT_RATIO_NUMBERS, SHOT_TYPES, POV_ANGLES } from '../constants';
import { selectImageFile } from '../lib/gemini';
import { PromptTextarea } from './PromptTextarea';

interface UpscaleModalProps {
  cells: GridCell[];
  initialIndex: number;
  aspectRatio: AspectRatio;
  globalPrompt: string;
  useGlobalPrompt: boolean;
  globalRefs: {
    images: {id: string, base64: string, mimeType: string}[];
  };
  onRegenerateCell: (cellId: string, prompt: string, model: string) => Promise<any>;
  onSaveExpandedResult: (cellId: string, result: { mediaId?: string; base64: string; mimeType: string }) => void;
  onUpdateCell?: (cellId: string, changes: Partial<GridCell>) => void;
  onClose: () => void;
  onUpscaleImage: (prompt: string, base64Src: string, mimeTypeSrc: string, aspect: string, model: string, imageSize?: string, extraRefs?: {base64: string, mimeType: string}[]) => Promise<{ base64: string, mimeType: string }>;
  generatingStates?: Record<string, { isGenerating: boolean, progress: number, status: string }>;
}

export const UpscaleModal: React.FC<UpscaleModalProps> = ({ cells, initialIndex, aspectRatio, globalPrompt, useGlobalPrompt, globalRefs, onRegenerateCell, onSaveExpandedResult, onUpdateCell, onClose, onUpscaleImage, generatingStates }) => {
  const validCells = cells.filter(c => c.result);
  const startIdx = validCells.findIndex(c => c.id === cells[initialIndex]?.id);

  const [currentIndex, setCurrentIndex] = useState(startIdx !== -1 ? startIdx : 0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [status, setStatus] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [model, setModel] = useState('Nano Banana Pro');
  const [localPrompt, setLocalPrompt] = useState('');

  const currentCell = validCells[currentIndex];

  const isMainProcessing = (currentCell && generatingStates?.[currentCell.id]?.isGenerating) || false;
  const isUpscaleProcessing = (currentCell && generatingStates?.[currentCell.id + '_upscale']?.isGenerating) || false;
  const combinedIsProcessing = isProcessing || isMainProcessing || isUpscaleProcessing;
  const combinedProgress = isMainProcessing ? generatingStates![currentCell!.id].progress : (isUpscaleProcessing ? generatingStates![currentCell!.id + '_upscale'].progress : progress);
  const combinedStatus = isMainProcessing ? generatingStates![currentCell!.id].status : (isUpscaleProcessing ? generatingStates![currentCell!.id + '_upscale'].status : status);

  const image = currentCell?.result;
  const currentUpscale = currentCell?.expandedResult;

  useEffect(() => {
    if (currentCell) setLocalPrompt(currentCell.refinementPrompt || '');
  }, [currentCell]);

  const navigate = useCallback((dir: 'prev' | 'next') => {
    setError(null);
    if (validCells.length <= 1) return;
    if (dir === 'prev') setCurrentIndex(prev => (prev > 0 ? prev - 1 : validCells.length - 1));
    else setCurrentIndex(prev => (prev < validCells.length - 1 ? prev + 1 : 0));
  }, [validCells.length]);

  const handleUpscale = async (targetSize: string = "1K"): Promise<{base64: string, mimeType: string} | null> => {
    if (!image || !currentCell || isProcessing) return null;
    setIsProcessing(true); setError(null); setProgress(5); setStatus('Preparing buffer...');
    const interval = setInterval(() => setProgress(p => p < 90 ? p + 2 : p), 600);
    try {
      setStatus(`Generating ${targetSize} detail...`);
      const extraRefs: {base64: string, mimeType: string}[] = [];

      // Pull in global reference images
      if (globalRefs.images) {
        globalRefs.images.forEach(r => extraRefs.push({ base64: r.base64, mimeType: r.mimeType || 'image/jpeg' }));
      }

      // Pull in local reference images
      if (currentCell.localRefs) {
         currentCell.localRefs.forEach(r => extraRefs.push({base64: r.base64, mimeType: r.mimeType}));
      }

      const originalPrompt = (useGlobalPrompt && !currentCell.prompt) ? globalPrompt : currentCell.prompt;
      const combinedPrompt = originalPrompt + (localPrompt ? " Additional refinements: " + localPrompt : "");
      const result = await onUpscaleImage("IDENTICAL RECONSTRUCTION OF THE FIRST IMAGE WITH STRICT STYLE RETENTION. Enhance pixels to 1k. 8k texture and masterwork detail. No creative changes. Use the other images only as references for details." + combinedPrompt, image.base64, image.mimeType, aspectRatio, model, targetSize, extraRefs);
      clearInterval(interval); setProgress(100);
      if (targetSize === "1K" || !currentUpscale) {
        onSaveExpandedResult(currentCell.id, { base64: result.base64, mimeType: result.mimeType });
      }
      return result;
    } catch (err: any) {
      clearInterval(interval); setError(err.message || 'Expansion failed.'); return null;
    } finally { setIsProcessing(false); setStatus(''); }
  };

  const handleRegenerate = async () => {
    if (!currentCell || isProcessing) return;
    setIsProcessing(true); setError(null); setProgress(5); setStatus('Refining shot...');
    const interval = setInterval(() => setProgress(p => p < 95 ? p + 3 : p), 400);
    try {
      await onRegenerateCell(currentCell.id, localPrompt, model);
      clearInterval(interval); setProgress(100);
    } catch (err: any) {
      clearInterval(interval); setError(err.message || 'Refinement failed.');
    } finally { setIsProcessing(false); setStatus(''); }
  };

  const handleDownload = async (label: string) => {
    const data = currentUpscale || image;
    if (!data) return;
    try {
      setStatus(`Preparing download...`);
      await Flow.download({ 
        base64: data.base64, 
        mimeType: data.mimeType || 'image/jpeg', 
        filename: `shot-${currentIndex + 1}-${label}.jpg` 
      });
      setStatus('');
    } catch (e) {
      setError('Download failed.'); setStatus('');
    }
  };

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'ArrowLeft') navigate('prev');
      if (e.key === 'ArrowRight') navigate('next');
      if (e.key === 'Escape') onClose();
      if ((e.metaKey || e.ctrlKey) && e.key === 'Enter' && !combinedIsProcessing) { e.preventDefault(); handleRegenerate(); }
    };
    window.addEventListener('keydown', handleKey); return () => window.removeEventListener('keydown', handleKey);
  }, [navigate, onClose, combinedIsProcessing]);

  if (!currentCell || !image) return null;
  const ratio = ASPECT_RATIO_NUMBERS[aspectRatio] || 1.77;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/98 backdrop-blur-2xl animate-in fade-in duration-300">
      <div className="relative w-full h-full flex flex-col overflow-hidden">
        <div className="flex items-center justify-between px-6 py-3 border-b border-white/5 bg-neutral-950 z-10">
          <div className="flex flex-col"><h3 className="text-[10px] font-bold text-white uppercase tracking-widest">Detail Review</h3><span className="text-[10px] text-gray-400 uppercase font-bold">{currentIndex + 1} per {validCells.length}</span></div>
          <button onClick={onClose} className="p-2 text-gray-400 hover:text-white rounded-full transition-all"><X size={26} strokeWidth={1.5} /></button>
        </div>
        <div className="flex-1 flex flex-col lg:flex-row overflow-hidden relative bg-black">
          <div className="flex-1 relative flex items-center justify-center p-4 lg:p-10 overflow-hidden">
            <div className="relative w-full h-full flex items-center justify-center" style={{ aspectRatio: String(ratio) }}>
              <img src={"data:" + (currentUpscale?.mimeType || image.mimeType) + ";base64," + (currentUpscale?.base64 || image.base64)} className="max-w-full max-h-full object-contain shadow-2xl rounded-sm" />
            </div>
            {combinedIsProcessing && <div className="absolute inset-0 z-50 flex flex-col items-center justify-center bg-black/80 backdrop-blur-md"><div className="flex flex-col items-center gap-5 w-64"><span className="text-[10px] font-bold uppercase tracking-widest text-gray-200 animate-pulse text-center">{combinedStatus}</span><div className="h-[1px] w-full bg-white/10 rounded-full overflow-hidden"><div className="h-full bg-white transition-all duration-500" style={{ width: combinedProgress + "%" }} /></div><span className="text-2xl font-bold text-white tabular-nums">{Math.round(combinedProgress)}%</span></div></div>}
          </div>
          <div className="w-full lg:w-[320px] p-8 flex flex-col gap-8 border-t lg:border-t-0 lg:border-l border-white/5 bg-neutral-950 z-10 overflow-y-auto dark-scrollbar">
            <div className="flex flex-col gap-6">
              <div className="flex flex-col gap-3">
                <SectionLabel>Scene Data</SectionLabel>
                <div className="p-4 bg-white/5 rounded-2xl flex flex-col gap-4 border border-white/5">
                  <div className="text-[11px] text-white/50 italic leading-relaxed font-medium bg-black/20 p-3 rounded-xl border border-white/5">"{(useGlobalPrompt && !currentCell.prompt) ? globalPrompt : currentCell.prompt}"</div>
                  <PromptTextarea value={localPrompt} onChange={setLocalPrompt} className="w-full bg-black/20 rounded-xl p-3 text-[11px] text-white italic outline-none border border-white/5 h-20" placeholder="Refine shot..." />
                  <div className="flex flex-wrap gap-2">
                    <select value={currentCell.shotType} onChange={(e) => { if(onUpdateCell) onUpdateCell(currentCell.id, { shotType: e.target.value }) }} className="bg-white/10 rounded-lg px-2 py-1 text-[9px] font-bold uppercase text-gray-300 outline-none">{SHOT_TYPES.map(s => <option key={s} value={s}>{s}</option>)}</select>
                    <select value={currentCell.pov} onChange={(e) => { if(onUpdateCell) onUpdateCell(currentCell.id, { pov: e.target.value }) }} className="bg-white/10 rounded-lg px-2 py-1 text-[9px] font-bold uppercase text-gray-300 outline-none">{POV_ANGLES.map(p => <option key={p} value={p}>{p}</option>)}</select>
                  </div>
                </div>
                <button onClick={handleRegenerate} disabled={combinedIsProcessing} className="w-full h-10 rounded-xl bg-white/5 hover:bg-white/10 text-[10px] font-bold uppercase text-gray-200 disabled:opacity-20 flex items-center justify-center gap-2"><RefreshCw size={14} className={combinedIsProcessing ? 'animate-spin' : ''} /> Regenerate Shot</button>
              </div>
            </div>
            <div className="flex flex-col gap-3 mt-auto">
              {!currentUpscale && !currentCell.isRefined ? (
                <PillButton variant="filled" onClick={() => handleUpscale('1K')} disabled={combinedIsProcessing} className="w-full h-12 bg-white/10 text-white" icon={<Sparkles size={18} />}>Enhance to 1K</PillButton>
              ) : (
                <div className="flex flex-col gap-2">
                  {currentCell.isRefined && !currentUpscale && (
                    <PillButton variant="filled" disabled={true} className="w-full h-12 bg-white/5 text-white/30" icon={<Sparkles size={18} />}>Enhance to 1K</PillButton>
                  )}
                  <div className="flex items-center justify-center gap-2 py-3 bg-white/5 border border-white/5 rounded-2xl mb-1"><Check size={14} className="text-gray-200" /><span className="text-[10px] font-bold text-gray-200 uppercase tracking-widest">Detail Ready</span></div>
                  <button onClick={() => handleDownload('1k')} className="h-12 rounded-xl bg-white text-black font-bold text-[10px] uppercase flex flex-col items-center justify-center gap-1 hover:bg-gray-200 transition-all"><Download size={14} /> Download 1K</button>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { Plus, Trash2, LayoutGrid, User, Trees, Image as ImageIcon, Sparkles, History, Loader2, Maximize2, X, Settings2, MousePointer2, Zap, Layers, ChevronRight, Download, Ban, Info, Wand2, AlertCircle } from 'lucide-react';
