import { SHOT_TYPES, POV_ANGLES, ASPECT_RATIO_NUMBERS, PRESET_STYLES } from './constants';

const PLACEHOLDERS = [
  "A cyberpunk detective story in a neon-drenched city... raining, highly cinematic, moody lighting.",
  "Fantasy adventure in an ancient enchanted forest... glowing flora, epic wide shots, magical atmosphere.",
