export default function App() {
  const [randomPlaceholder] = useState(() => PLACEHOLDERS[Math.floor(Math.random() * PLACEHOLDERS.length)]);
  const [sessions, setSessions] = useState<GridSession[]>([]);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [generatingStates, setGeneratingStates] = useState<Record<string, { isGenerating: boolean, progress: number, status: string }>>({});
  const generatingStatesRef = useRef(generatingStates);
  useEffect(() => { generatingStatesRef.current = generatingStates; }, [generatingStates]);

  const [error, setError] = useState<string | null>(null);
  const [selectedCellIndex, setSelectedCellIndex] = useState<number | null>(null);
  const [selectedMulti, setSelectedMulti] = useState<number[]>([]);
  const [isFeedOpen, setIsFeedOpen] = useState(false);
  const [isProcessingScript, setIsProcessingScript] = useState(false);
  const [showHistoryHint, setShowHistoryHint] = useState(false);
  const [showTutorial, setShowTutorial] = useState(false);
  const [showWelcome, setShowWelcome] = useState(true);

  const [newStyleName, setNewStyleName] = useState('');
  const [newStylePrompt, setNewStylePrompt] = useState('');
  const [isAddingStyle, setIsAddingStyle] = useState(false);

  const [hasApiKey, setHasApiKey] = useState(true);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && window.aistudio.hasSelectedApiKey) {
        // @ts-ignore
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    // @ts-ignore
    if (window.aistudio && window.aistudio.openSelectKey) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
    } else {
      setHasApiKey(true);
    }
  };

  const activeSession = sessions.find(s => s.id === activeSessionId);
  const activeSessionRef = useRef<GridSession | undefined>(activeSession);
  useEffect(() => { activeSessionRef.current = activeSession; }, [activeSession]);

  useEffect(() => {
    const id = 'grid-architect-styles-v4';
    if (!document.getElementById(id)) {
      const style = document.createElement('style');
      style.id = id;
      style.textContent = `
        @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
        .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
        .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #333 transparent; }
        .dark-scrollbar::-webkit-scrollbar { width: 3px; }
        .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #333; border-radius: 9999px; }
        html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Inter', sans-serif; overflow: hidden; }
        .focus-ring:focus-within { background: rgba(255,255,255,0.06); }
        input[type=number]::-webkit-inner-spin-button, input[type=number]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
        @keyframes hint-bounce { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(5px); } }
        .hint-animate { animation: hint-bounce 2s infinite; }
      `;
      document.head.appendChild(style);
    }
  }, []);

  const [showNewSessionModal, setShowNewSessionModal] = useState(false);
  const createNewSession = useCallback((force = false) => {
    const current = activeSessionRef.current;

    const hasMeaningfulContent = current && (
      current.globalPrompt?.trim() !== '' || 
      current.globalRefs.images?.length > 0 || 
      current.cells.some(c => c.prompt?.trim() !== '' || c.result || c.sketchBase64) ||
      current.scriptContent?.trim() !== ''
    );

    if (!force && hasMeaningfulContent) {
      setShowNewSessionModal(true);
      return;
    }

    const newSession: GridSession = {
      id: "sess-" + Date.now() + Math.random().toString(36).substring(7), timestamp: Date.now(), layout: '2x2', rows: 2, cols: 2, aspectRatio: '16:9', model: current?.model || 'Nano Banana 2', globalPrompt: '', useGlobalPrompt: true, selectedStyle: 'inherit', customStyles: current?.customStyles || [], globalRefs: { images: [] },
      cells: Array.from({ length: 4 }).map((_, i) => ({ id: "cell-" + i + "-" + Date.now() + Math.random().toString(36).substring(7), prompt: '', shotType: SHOT_TYPES[3], pov: POV_ANGLES[0] }))
    };
    setSessions(prev => [newSession, ...prev]);
    setActiveSessionId(newSession.id);
    setError(null);
    setShowNewSessionModal(false);
  }, []);

  const changeGridLayout = useCallback((layout: GridLayout, aspect?: AspectRatio, customDim?: {r: number, c: number}) => {
    const current = activeSessionRef.current;
    if (!current) return;
    const isCurrentlyGenerating = generatingStatesRef.current[current.id]?.isGenerating;
    if (isCurrentlyGenerating) return; 

    let nextAspect: AspectRatio = aspect || current.aspectRatio || '16:9';
    let nextPrevAspect = current.prevAspectRatio;

    if (layout === '1x4' && current.layout !== '1x4') {
        nextPrevAspect = current.aspectRatio;
        nextAspect = '9:16';
    } 
    else if (layout !== '1x4' && current.layout === '1x4') {
        if (current.prevAspectRatio) {
            nextAspect = current.prevAspectRatio;
            nextPrevAspect = undefined;
        }
    } 
    else if (aspect && layout !== '1x4') {
        nextAspect = aspect;
        nextPrevAspect = undefined;
    }

    let rows = 2, cols = 2;
    if (layout === '2x2') { rows = 2; cols = 2; }
    else if (layout === '3x3') { rows = 3; cols = 3; }
    else if (layout === '1x4') { rows = 4; cols = 1; }
    else if (layout === 'custom' && customDim) { rows = customDim.r; cols = customDim.c; }
    else if (layout === 'custom') { rows = current.rows; cols = current.cols; }
    const cellCount = rows * cols;

    const mapCells = (oldCells: GridCell[]) => {
      const newCells = [...oldCells];
      while (newCells.length < cellCount) {
        newCells.push({ id: "cell-" + newCells.length + "-" + Date.now() + Math.random().toString(36).substring(7), prompt: '', shotType: SHOT_TYPES[3], pov: POV_ANGLES[0] });
      }
      return newCells;
    };

    setSessions(prev => prev.map(s => s.id === current.id ? {
      ...s,
      layout,
      rows,
      cols,
      aspectRatio: nextAspect,
      prevAspectRatio: nextPrevAspect,
      cells: mapCells(s.cells),
      masterGridResult: (s.layout === layout && s.aspectRatio === nextAspect && s.rows === rows && s.cols === cols) ? s.masterGridResult : undefined
    } : s));
  }, []);

  const hasInitialized = useRef(false);
  useEffect(() => { if (sessions.length === 0 && !hasInitialized.current) { hasInitialized.current = true; createNewSession(); } }, [createNewSession, sessions.length]);

  const updateSession = useCallback((id: string, update: Partial<GridSession>) => {
    setSessions(prev => prev.map(s => s.id === id ? { ...s, ...update } : s));
  }, []);

  const updateActiveSession = useCallback((update: Partial<GridSession>) => {
    if (activeSessionId) updateSession(activeSessionId, update);
  }, [activeSessionId, updateSession]);

  const handleSelectReference = async (type: 'global-ref' | 'cell-sketch' | 'cell-local-ref', cellId?: string) => {
    try {
      const media = await selectImageFile();
      if (!media) return;
      setSessions(prev => prev.map(s => {
        if (s.id !== activeSessionId) return s;
        if (type === 'cell-sketch' && cellId) return { ...s, cells: s.cells.map(c => c.id === cellId ? { ...c, sketchBase64: media.base64, sketchMimeType: media.mimeType, isModified: true } : c) };
        else if (type === 'cell-local-ref' && cellId) return { ...s, cells: s.cells.map(c => c.id === cellId ? { ...c, localRefs: [...(c.localRefs || []), { id: `ref-${Date.now()}`, base64: media.base64, mimeType: media.mimeType }], isModified: true } : c) };
        else if (type === 'global-ref') return { ...s, globalRefs: { ...s.globalRefs, images: [...(s.globalRefs.images || []), { id: `ref-${Date.now()}`, base64: media.base64, mimeType: media.mimeType }] } };
        return s;
      }));
    } catch (e) {
      console.error(e);
    }
  };

  const handleClearReference = (type: 'global-ref' | 'cell-sketch' | 'cell-local-ref', cellId?: string, localRefId?: string) => {
    setSessions(prev => prev.map(s => {
      if (s.id !== activeSessionId) return s;
      if (type === 'cell-sketch' && cellId) return { ...s, cells: s.cells.map(c => c.id === cellId ? { ...c, sketchMediaId: undefined, sketchBase64: undefined, sketchMimeType: undefined, isModified: true } : c) };
      else if (type === 'cell-local-ref' && cellId && localRefId) return { ...s, cells: s.cells.map(c => c.id === cellId ? { ...c, localRefs: (c.localRefs || []).filter(r => r.id !== localRefId), isModified: true } : c) };
      else if (type === 'global-ref' && localRefId) return { ...s, globalRefs: { ...s.globalRefs, images: (s.globalRefs.images || []).filter(r => r.id !== localRefId) } };
      return s;
    }));
  };

  const handleGenerateGrid = async () => {
    const session = activeSessionRef.current;
    if (!session) return;
    const sessionId = session.id;
    setGeneratingStates(prev => ({ ...prev, [sessionId]: { isGenerating: true, progress: 5, status: 'Architecting...' } }));
    setError(null);
    const clearedCells = session.cells.map(c => ({ ...c, result: undefined, expandedResult: undefined, isModified: false }));
    updateSession(sessionId, { cells: clearedCells });
    const timer = setInterval(() => setGeneratingStates(prev => {
        if (!prev[sessionId]) return prev;
        return { ...prev, [sessionId]: { ...prev[sessionId], progress: prev[sessionId].progress < 65 ? prev[sessionId].progress + Math.random() * 2 : prev[sessionId].progress } };
    }), 800);
    try {
      const { rows, cols, aspectRatio, model, globalRefs, useGlobalPrompt, globalPrompt, cells, selectedStyle, customStyles, layout } = session;
      const allStyles = [...PRESET_STYLES, ...customStyles];
      const stylePrompt = allStyles.find(s => s.id === selectedStyle)?.prompt || '';
      const arrangement = rows > cols ? (rows + " rows and " + cols + " columns") : (rows + "x" + cols + " grid");
      const aspectNames: Record<string, string> = {
        '1:1': '1:1 perfect square',
        '16:9': '16:9 widescreen landscape',
        '9:16': '9:16 vertical portrait',
        '4:3': '4:3 standard landscape',
        '3:4': '3:4 vertical portrait'
      };
      const constraint = (layout === '1x4') ? '16:9 widescreen landscape' : (aspectNames[aspectRatio] || 'distinct');
      let gridPrompt = "A multiple-panel composition consisting of exactly " + (rows * cols) + " distinct images, perfectly divided into a geometric grid of exactly " + rows + " rows and " + cols + " columns. CRITICAL: The entire generated image MUST be an exact " + arrangement + " with absolutely no margins, borders, frames, or gaps between the images. DO NOT generate more or fewer images than exactly " + (rows * cols) + " total images in the grid. Style: " + stylePrompt + ". ";

      const refs: { base64: string, mimeType: string }[] = [];
      if (globalRefs.images) {
        globalRefs.images.forEach(r => refs.push({ base64: r.base64, mimeType: r.mimeType || 'image/jpeg' }));
      }

      const activeCells = cells.slice(0, rows * cols);
      activeCells.forEach((cell, i) => {
        const cellP = useGlobalPrompt ? globalPrompt : cell.prompt;
        if (cellP || useGlobalPrompt) gridPrompt += "[SHOT " + (i + 1) + ": " + cell.shotType + ", " + cell.pov + ", " + (cellP || globalPrompt);
        if (cell.sketchBase64) {
          gridPrompt += " - CRITICAL: A reference sketch image is provided for this shot. Use this sketch strictly for layout and spatial arrangement ONLY.";
          refs.push({ base64: cell.sketchBase64, mimeType: cell.sketchMimeType || 'image/jpeg' });
        }
        if (cellP || useGlobalPrompt) gridPrompt += "] ";
      });

      if (gridPrompt.length > 3950) {
        clearInterval(timer);
        setError("Prompt is too long. Please shorten it and try to regenerate.");
        setGeneratingStates(prev => { const n = { ...prev }; delete n[sessionId]; return n; });
        return;
      }

      let targetRatio: AspectRatio = layout === '1x4' ? '9:16' : aspectRatio;
      setGeneratingStates(prev => ({ ...prev, [sessionId]: { ...prev[sessionId], status: 'Master generation...' } }));

      const result = await generateImage(gridPrompt, refs, targetRatio, model);
      if (!result || !result.base64) throw new Error("Empty visual buffer.");

      clearInterval(timer); setGeneratingStates(prev => ({ ...prev, [sessionId]: { ...prev[sessionId], progress: 70, status: 'Slicing buffer...' } }));
      const img = await new Promise<HTMLImageElement>((resolve, reject) => {
        const i = new Image(); i.crossOrigin = "anonymous"; i.onload = () => resolve(i); i.onerror = () => reject(new Error('Visual buffer fault.'));
        i.src = "data:" + result.mimeType + ";base64," + result.base64;
      });
      const canvas = document.createElement('canvas'); const ctx = canvas.getContext('2d'); if (!ctx) throw new Error('Hardware layer fault.');
      const cellWidth = Math.floor(img.width / cols); const cellHeight = Math.floor(img.height / rows);
      const newCells = [...clearedCells];
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const idx = r * cols + c; if (!newCells[idx]) continue;
          canvas.width = cellWidth; canvas.height = cellHeight; ctx.drawImage(img, c * cellWidth, r * cellHeight, cellWidth, cellHeight, 0, 0, cellWidth, cellHeight);
          newCells[idx] = { ...newCells[idx], result: { base64: canvas.toDataURL('image/jpeg', 0.9).split(',')[1], mimeType: 'image/jpeg' } };
          const p = Math.round(70 + ((idx + 1) / (rows * cols)) * 30);
          setGeneratingStates(prev => ({ ...prev, [sessionId]: { ...prev[sessionId], progress: p } }));
        }
      }
      setSessions(prev => prev.map(s => s.id === sessionId ? { ...s, cells: newCells, masterGridResult: { base64: result.base64, mimeType: result.mimeType } } : s));
    } catch (err: any) {
      clearInterval(timer); setError(err.message || 'Architect fault.');
    }
    finally {
      setGeneratingStates(prev => { const n = { ...prev }; delete n[sessionId]; return n; });
    }
  };

  const handleDownloadGrid = async () => {
    const session = activeSessionRef.current;
    if (!session) return;

    const activeCells = session.cells.slice(0, session.rows * session.cols);
    if (!activeCells.some(c => c.result || c.expandedResult)) return;

    const loadImg = (src: string): Promise<HTMLImageElement> => new Promise((resolve, reject) => {
      const img = new Image(); img.onload = () => resolve(img); img.onerror = reject; img.src = src;
    });

    try {
      const validCells = activeCells.filter(c => c.result || c.expandedResult);
      if (validCells.length === 0) return;

      const imagesInfo = await Promise.all(
        activeCells.map(async (c, i) => {
          const r = c.expandedResult || c.result;
          if (!r) return null;
          const img = await loadImg(`data:${r.mimeType};base64,${r.base64}`);
          return { img, i };
        })
      );

      const validImagesInfo = imagesInfo.filter(Boolean) as {img: HTMLImageElement, i: number}[];
      if (validImagesInfo.length === 0) return;

      const firstImg = validImagesInfo[0].img;
      const imgW = firstImg.width;
      const imgH = firstImg.height;
      const gap = 8;

      const canvas = document.createElement('canvas');
      canvas.width = (session.cols * imgW) + ((session.cols - 1) * gap);
      canvas.height = (session.rows * imgH) + ((session.rows - 1) * gap);
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      ctx.fillStyle = '#111'; ctx.fillRect(0, 0, canvas.width, canvas.height);

      validImagesInfo.forEach(({ img, i }) => {
        const col = i % session.cols;
        const row = Math.floor(i / session.cols);
        ctx.drawImage(img, col * (imgW + gap), row * (imgH + gap), imgW, imgH);
      });

      const base64 = canvas.toDataURL('image/jpeg', 0.95).split(',')[1];
      await Flow.download({ 
        base64, 
        mimeType: 'image/jpeg', 
        filename: `storyboard-${session.id}.jpg` 
      });
    } catch(err: any) {
      console.error(err); setError("Failed to generate grid image");
    }
  };

  const handleEnhanceGrid = async () => {
    const session = activeSessionRef.current;
    if (!session) return;
    const sessionId = session.id;
    setGeneratingStates(prev => ({ ...prev, [sessionId]: { isGenerating: true, progress: 10, status: 'Enhancing...' } }));
    try {
      const { globalRefs } = session;
      const extraRefs: { base64: string, mimeType: string }[] = [];
      if (globalRefs.images) globalRefs.images.forEach(r => extraRefs.push({ base64: r.base64, mimeType: r.mimeType || 'image/jpeg' }));

      const activeCells = session.cells.slice(0, session.rows * session.cols);
      for (let i = 0; i < activeCells.length; i++) {
        const cell = activeCells[i];
        if (cell.result && !cell.expandedResult && !cell.isRefined) {
          const cellRefs = [...extraRefs];
          if (cell.localRefs) cell.localRefs.forEach(r => cellRefs.push({ base64: r.base64, mimeType: r.mimeType }));
          setGeneratingStates(prev => ({ ...prev, [sessionId]: { ...prev[sessionId], progress: 10 + (i / activeCells.length) * 85, status: `Enhancing shot ${i+1}...` } }));
          const cellAspect = session.layout === '1x4' ? '16:9' : session.aspectRatio;
          const res = await upscaleImage("IDENTICAL RECONSTRUCTION OF THE FIRST IMAGE WITH STRICT STYLE RETENTION. Enhance pixels to 1k. 8k texture and masterwork detail. No creative changes. Use the other images only as references for details.", cell.result.base64, cell.result.mimeType, cellAspect, session.model || 'Nano Banana 2', "1K", cellRefs);
          setSessions(prev => prev.map(s => s.id === sessionId ? { ...s, cells: s.cells.map(c => c.id === cell.id ? { ...c, expandedResult: { base64: res.base64, mimeType: res.mimeType } } : c) } : s));
        }
      }
      setGeneratingStates(prev => { const n = { ...prev }; delete n[sessionId]; return n; });
    } catch(err: any) {
      setError(err.message || "Enhancement failed");
      setGeneratingStates(prev => { const n = { ...prev }; delete n[sessionId]; return n; });
    }
  };

  const handleBreakdownScript = async () => {
    const session = activeSessionRef.current;
    if (!session || !session.scriptContent) return;

    if (session.scriptContent.length > 3800) {
      setError("Script is too long. Please shorten it and try to break it down into shots again.");
      return;
    }

    setIsProcessingScript(true); setError(null);
    try {
      const numCells = session.rows * session.cols;
      const breakdowns = await breakdownScript(session.scriptContent, numCells, SHOT_TYPES as any, POV_ANGLES as any);
      const newCells = [...session.cells];
      for (let i = 0; i < numCells && i < breakdowns.length; i++) {
        newCells[i] = { ...newCells[i], prompt: breakdowns[i].prompt, shotType: breakdowns[i].shotType, pov: breakdowns[i].pov };
      }
      updateActiveSession({ cells: newCells });
    } catch (err: any) {
      setError(err.message || 'Script breakdown failed.');
    } finally {
      setIsProcessingScript(false);
    }
  };

  const handleRegenerateCell = async (cellId: string, customPrompt: string, model: string) => {
    const session = activeSessionRef.current;
    if (!session) return;
    setGeneratingStates(prev => ({ ...prev, [cellId]: { isGenerating: true, progress: 10, status: 'Refining...' } }));
    try {
      const cellIdx = session.cells.findIndex(c => c.id === cellId); if (cellIdx === -1) return;
      const { globalRefs, selectedStyle, customStyles, aspectRatio } = session;
      const allStyles = [...PRESET_STYLES, ...customStyles];
      const stylePrompt = allStyles.find(s => s.id === selectedStyle)?.prompt || '';
      const cell = session.cells[cellIdx];
      let prompt = ""; const refs: { base64: string, mimeType: string }[] = [];
      let res; const cellAspect = session.layout === '1x4' ? '16:9' : aspectRatio;

      if (cell.sketchBase64) {
        prompt = "Sketch reference for layout ONLY. Detail using: Angle: " + cell.pov + ", Shot: " + cell.shotType + ". Prompt: " + (customPrompt || cell.prompt) + ". Style: " + stylePrompt;
        refs.push({ base64: cell.sketchBase64, mimeType: cell.sketchMimeType! });
        if (cell.result) refs.push({ base64: cell.result.base64, mimeType: cell.result.mimeType });
        if (session.masterGridResult) refs.push({ base64: session.masterGridResult.base64, mimeType: session.masterGridResult.mimeType });
        if (globalRefs.images) globalRefs.images.forEach(r => refs.push({ base64: r.base64, mimeType: r.mimeType || 'image/jpeg' }));
        if (cell.localRefs) cell.localRefs.forEach((ref) => refs.push({ base64: ref.base64, mimeType: ref.mimeType }));
        res = await generateImage(prompt, refs, cellAspect, model);
      } else {
        prompt = "Refine the first image with the following instructions. Maintain the base image structure, characters, and visual style strictly, but apply these camera and structural modifications: Shot Type : " + cell.shotType + ". Camera Angle: " + cell.pov + ". Additional details: " + customPrompt;
        if (session.masterGridResult) refs.push({ base64: session.masterGridResult.base64, mimeType: session.masterGridResult.mimeType });
        if (globalRefs.images) globalRefs.images.forEach(r => refs.push({ base64: r.base64, mimeType: r.mimeType || 'image/jpeg' }));
        if (cell.localRefs) cell.localRefs.forEach((ref) => refs.push({ base64: ref.base64, mimeType: ref.mimeType }));
        res = await refineImage(prompt, cell.result!.base64, cell.result!.mimeType, cellAspect, model, refs.length > 0 ? refs : undefined);
      }

      const newCells = session.cells.map(c => {
        if (c.id === cellId) {
          return { 
            ...c, 
            refinementPrompt: customPrompt, 
            expandedResult: undefined, 
            result: { base64: res.base64, mimeType: res.mimeType }, 
            isModified: false, 
            isRefined: true 
          };
        }
        return c;
      });

      const newSess: GridSession = { ...session, id: "sess-" + Date.now(), timestamp: Date.now(), cells: newCells };
      setSessions(prev => [newSess, ...prev]);
      setActiveSessionId(newSess.id);
      return res;
    } catch (err: any) {
      console.error(err); throw err;
    } finally {
      setGeneratingStates(prev => { const n = { ...prev }; delete n[cellId]; return n; });
    }
  };

  const handleSaveExpandedResult = (cellId: string, result: { base64: string; mimeType: string }) => {
    setSessions(prev => {
      const idx = prev.findIndex(s => s.id === activeSessionId); if (idx === -1) return prev;
      const current = prev[idx];
      const newCells = current.cells.map(c => c.id === cellId ? { ...c, expandedResult: result } : c);
      const newSess = { ...current, id: "sess-" + Date.now(), cells: newCells };
      const copy = [...prev]; copy.splice(idx + 1, 0, newSess);
      setActiveSessionId(newSess.id);
      return copy;
    });
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') { setSelectedMulti([]); setSelectedCellIndex(null); }
    if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
      e.preventDefault();
      const isG = activeSessionId ? generatingStates[activeSessionId]?.isGenerating : false;
      if (selectedCellIndex === null && !isG && activeSession && hasPromptContent) handleGenerateGrid();
    }
  };

  const handleUpscaleMulti = async () => {
    if (!activeSession) return;
    const targets = [...selectedMulti]; setSelectedMulti([]);

    const { globalRefs } = activeSession;
    const extraRefs: { base64: string, mimeType: string }[] = [];
    if (globalRefs.images) globalRefs.images.forEach(r => extraRefs.push({ base64: r.base64, mimeType: r.mimeType || 'image/jpeg' }));

    setGeneratingStates(prev => {
      const next = { ...prev };
      for (const idx of targets) {
        const cell = activeSession.cells[idx];
        next[cell.id + '_upscale'] = { isGenerating: true, progress: 10, status: 'Upscaling...' };
      }
      return next;
    });

    const upscaledResults: {idx: number, cellId: string, result: any}[] = [];
    await Promise.all(targets.map(async (idx) => {
      const cell = activeSession.cells[idx];
      const res = cell.expandedResult || cell.result;
      if (!res) return;
      try {
        const cellRefs = [...extraRefs];
        if (cell.localRefs) cell.localRefs.forEach(r => cellRefs.push({ base64: r.base64, mimeType: r.mimeType }));

        const baseP = (activeSession.useGlobalPrompt && !cell.prompt) ? activeSession.globalPrompt : (cell.prompt || '');
        const upscaled = await upscaleImage("IDENTICAL RECONSTRUCTION OF THE FIRST IMAGE WITH STRICT STYLE RETENTION. Enhance pixels to 1k. 8k texture and masterwork detail. No creative changes. Use the other images only as references for details." + baseP, res.base64, res.mimeType || 'image/jpeg', activeSession.layout === '1x4' ? '16:9' : activeSession.aspectRatio, activeSession.model, '1K', cellRefs);
        upscaledResults.push({ idx, cellId: cell.id, result: upscaled });

        await Flow.download({ 
          base64: upscaled.base64, 
          mimeType: upscaled.mimeType || 'image/jpeg', 
          filename: `grid-shot-${idx+1}-enhanced.jpg` 
        });
      } catch (err: any) {
        setError(`Upscale failed for shot ${idx+1}`);
      } finally {
        setGeneratingStates(prev => { const n = {...prev}; delete n[cell.id + '_upscale']; return n; });
      }
    }));

    if (upscaledResults.length > 0) {
      setSessions(prev => {
        const idx = prev.findIndex(s => s.id === activeSession.id); if (idx === -1) return prev;
        const current = prev[idx]; const newCells = [...current.cells];
        for (const {cellId, result} of upscaledResults) {
          const cidx = newCells.findIndex(c => c.id === cellId);
          if (cidx !== -1) newCells[cidx] = { ...newCells[cidx], expandedResult: { base64: result.base64, mimeType: result.mimeType } };
        }
        const newSess = { ...current, id: "sess-" + Date.now(), cells: newCells };
        const copy = [...prev]; copy.splice(idx + 1, 0, newSess);
        setActiveSessionId(newSess.id);
        return copy;
      });
    }
  };

  const hasPromptContent = activeSession && (
    activeSession.useGlobalPrompt 
      ? activeSession.globalPrompt.trim() !== '' 
      : activeSession.cells.slice(0, activeSession.rows * activeSession.cols).some(c => c.prompt.trim() !== '')
  );
  const aspectOptions = ['1:1', '16:9', '9:16', '4:3', '3:4'];
  const disabledAspects = activeSession?.layout === '1x4' ? aspectOptions.filter(o => o !== '9:16') : [];
  const boxRatioVal = activeSession ? (ASPECT_RATIO_NUMBERS[activeSession.aspectRatio] || 1.77) : 1.77;
  const totalGridRatio = activeSession?.layout === '1x4' ? 0.5625 : (activeSession ? (boxRatioVal * activeSession.cols) / activeSession.rows : 1);

  const handleAddCustomStyle = () => {
    if (!newStyleName || !newStylePrompt || !activeSession) return;
    const style: CustomStyle = { id: "custom-" + Date.now(), name: newStyleName, prompt: newStylePrompt };
    updateActiveSession({ customStyles: [...activeSession.customStyles, style], selectedStyle: style.id });
    setNewStyleName(''); setNewStylePrompt(''); setIsAddingStyle(false);
  };

  const allStylesMerged = useMemo(() => {
    const list = [...PRESET_STYLES];
    if (activeSession) list.push(...activeSession.customStyles);
    return list;
  }, [activeSession?.customStyles]);

  const currentStyleName = useMemo(() => {
    if (!activeSession) return 'Style from References';
    return allStylesMerged.find(s => s.id === activeSession.selectedStyle)?.name || 'Style from References';
  }, [activeSession?.selectedStyle, allStylesMerged]);

  if (!hasApiKey) {
    return (
      <div className="flex h-screen w-screen bg-[#0e0e0e] items-center justify-center text-white p-8">
        <div className="flex flex-col items-center gap-6 max-w-md bg-[#161616] p-10 rounded-[32px] border border-gray-600 shadow-2xl">
          <div className="w-16 h-16 bg-gray-500 rounded-full flex items-center justify-center shadow-inner">
            <Sparkles size={24} className="text-white" />
          </div>
          <h2 className="text-xl font-bold tracking-tight text-white mb-2">API Key Required</h2>
          <PillButton onClick={handleSelectKey} variant="solid" className="w-full mt-4 h-12">Configure Access</PillButton>
        </div>
      </div>
    );
  }

  const globalIsGen = activeSessionId ? generatingStates[activeSessionId]?.isGenerating : false;

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden" onKeyDown={handleKeyDown}>
      {showWelcome && <WelcomeModal onClose={() => setShowWelcome(false)} />}
      {showTutorial && <TutorialOverlay onClose={() => setShowTutorial(false)} />}

      {selectedMulti.length > 0 && activeSession && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-50 bg-black/90 backdrop-blur-xl border border-white/10 rounded-2xl p-2 px-4 shadow-2xl flex items-center gap-4 animate-in slide-in-from-bottom-2">
          <span className="text-[11px] font-bold text-white/50">{selectedMulti.length} selected</span>
          <div className="flex items-center gap-2">
            <PillButton variant="filled" onClick={handleUpscaleMulti} className="h-8 text-[10px]" icon={<Sparkles size={14}/>}>Enhance & Download</PillButton>
          </div>
          <button onClick={() => setSelectedMulti([])} className="text-white/40 hover:text-white p-1 ml-2"><X size={14}/></button>
        </div>
      )}

      <div className={`w-[340px] h-full border-r border-white/5 flex flex-col overflow-hidden shrink-0 relative ${globalIsGen ? 'opacity-50' : ''}`}>
        {globalIsGen && <div className="absolute inset-0 z-[100] cursor-not-allowed" />}
        <div className="flex-1 overflow-y-auto dark-scrollbar scroll-smooth">
          <div className="p-4 flex flex-col gap-6">
            <div className="flex items-center justify-between">
              <PillButton variant="filled" icon={<Plus size={14} />} onClick={() => createNewSession()} disabled={globalIsGen} className="h-8 rounded-full w-auto px-4">New grid</PillButton>
              <button onClick={() => setShowTutorial(true)} className="text-gray-400 hover:text-white transition-colors flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider">
                <Info size={14} /> Tutorial
              </button>
            </div>
            <div className="flex flex-col gap-2">
              <SectionLabel>Configuration</SectionLabel>
              <div className="flex flex-col gap-1.5">
                <FieldDropdown label="Engine" value={activeSession?.model || 'Nano Banana 2'} options={['Nano Banana 2', 'Nano Banana Pro']} onChange={(val) => updateActiveSession({ model: val })} />
                <FieldDropdown label="Format Ratio" value={activeSession?.aspectRatio || '16:9'} options={aspectOptions} disabledOptions={disabledAspects} onChange={(val) => { changeGridLayout(activeSession?.layout || '2x2', val as AspectRatio); }} />
              </div>
            </div>
            <div className="flex flex-col gap-2">
              <SectionLabel>Aesthetic</SectionLabel>
              <FieldDropdown label="Visual Logic" value={currentStyleName} options={[...allStylesMerged.map(s => s.name), '+ Custom Style']} onChange={(val) => { if (val === '+ Custom Style') setIsAddingStyle(true); else { const found = allStylesMerged.find(i => i.name === val); if (found) updateActiveSession({ selectedStyle: found.id }); } }} />
            </div>
            <div className="flex flex-col gap-2 relative">
              {isProcessingScript && <div className="absolute inset-0 z-10 flex items-center justify-center bg-[#0C0C0C]/50 backdrop-blur-[1px] rounded-xl cursor-not-allowed border border-white/5"><Ban size={20} className="text-white/40" /></div>}
              <div className="grid grid-cols-4 gap-1 w-full">
                <button disabled={isProcessingScript} onClick={() => changeGridLayout('2x2')} className={"py-3 rounded-xl flex items-center justify-center transition-all " + (activeSession?.layout === '2x2' ? 'bg-white/10 text-white shadow-lg border border-white/5' : 'bg-white/5 text-gray-400 hover:text-white/80')}><Grid2x2 size={18} /></button>
                <button disabled={isProcessingScript} onClick={() => changeGridLayout('3x3')} className={"py-3 rounded-xl flex items-center justify-center transition-all " + (activeSession?.layout === '3x3' ? 'bg-white/10 text-white shadow-lg border border-white/5' : 'bg-white/5 text-gray-400 hover:text-white/80')}><Grid3x3 size={18} /></button>
                <button disabled={isProcessingScript} onClick={() => changeGridLayout('1x4')} className={"py-3 rounded-xl flex items-center justify-center transition-all " + (activeSession?.layout === '1x4' ? 'bg-white/10 text-white shadow-lg border border-white/5' : 'bg-white/5 text-gray-400 hover:text-white/80')}><Grid1x4 size={18} /></button>
                <button disabled={isProcessingScript} onClick={() => changeGridLayout('custom')} className={"py-3 rounded-xl flex items-center justify-center transition-all " + (activeSession?.layout === 'custom' ? 'bg-white/10 text-white shadow-lg border border-white/5' : 'bg-white/5 text-gray-400 hover:text-white/80')}><Settings2 size={18} /></button>
              </div>
              {activeSession?.layout === 'custom' && (
                <div className="flex gap-1.5 mt-2 animate-in fade-in slide-in-from-top-1 duration-200">
                  <FieldDropdown 
                    label="Rows" 
                    value={String(activeSession.rows)} 
                    options={['1', '2', '3', '4', '5']} 
                    onChange={(val) => changeGridLayout('custom', undefined, { r: parseInt(val), c: activeSession.cols })}
                    className="flex-1"
                  />
                  <FieldDropdown 
                    label="Cols" 
                    value={String(activeSession.cols)} 
                    options={['1', '2', '3', '4', '5']} 
                    onChange={(val) => changeGridLayout('custom', undefined, { r: activeSession.rows, c: parseInt(val) })}
                    className="flex-1"
                  />
                </div>
              )}
            </div>
            <div className="flex flex-col gap-4 p-4 bg-white/5 rounded-2xl border border-white/[0.02]">
              <div className="flex flex-col gap-3">
                <button onClick={() => updateActiveSession({ useGlobalPrompt: true, scriptMode: false })} className={"flex flex-col items-start gap-1 p-4 rounded-xl transition-all text-left " + (activeSession?.useGlobalPrompt && !activeSession?.scriptMode ? 'bg-white/10 ring-1 ring-white/10' : 'bg-white/5 hover:bg-white/[0.07] opacity-60')}>
                  <div className="flex items-center gap-2"><Zap size={14} className={activeSession?.useGlobalPrompt && !activeSession?.scriptMode ? "text-yellow-400" : "text-gray-400"} /><span className="text-[10px] font-bold uppercase tracking-wider">Unified Theme</span></div>
                  <span className="text-[9px] text-gray-400 italic leading-tight">Master prompt drives the entire grid.</span>
                </button>
                <button onClick={() => updateActiveSession({ useGlobalPrompt: false, scriptMode: false })} className={"flex flex-col items-start gap-1 p-4 rounded-xl transition-all text-left " + (!activeSession?.useGlobalPrompt && !activeSession?.scriptMode ? 'bg-white/10 ring-1 ring-white/10' : 'bg-white/5 hover:bg-white/[0.07] opacity-60')}>
                  <div className="flex items-center gap-2"><Layers size={14} className={!activeSession?.useGlobalPrompt && !activeSession?.scriptMode ? "text-blue-400" : "text-gray-400"} /><span className="text-[10px] font-bold uppercase tracking-wider">Sequence</span></div>
                  <span className="text-[9px] text-gray-400 italic leading-tight">Unique prompt and camera logic per frame.</span>
                </button>
                <button onClick={() => updateActiveSession({ scriptMode: true, useGlobalPrompt: false })} className={"flex flex-col items-start gap-1 p-4 rounded-xl transition-all text-left " + (activeSession?.scriptMode ? 'bg-white/10 ring-1 ring-white/10' : 'bg-white/5 hover:bg-white/[0.07] opacity-60')}>
                  <div className="flex items-center gap-2"><Wand2 size={14} className={activeSession?.scriptMode ? "text-purple-400" : "text-gray-400"} /><span className="text-[10px] font-bold uppercase tracking-wider">Prompt Wizard</span></div>
                  <span className="text-[9px] text-gray-400 italic leading-tight">Auto-storyboard from script.</span>
                </button>
              </div>
              {activeSession?.scriptMode && (
                <div className="flex flex-col gap-2 mt-1">
                  <textarea value={activeSession.scriptContent || ''} onChange={(e) => updateActiveSession({ scriptContent: e.target.value })} placeholder="Paste script..." className="w-full h-32 bg-white/10 rounded-xl p-3 text-[11px] outline-none transition-colors resize-none" />
                  <div className="flex justify-end px-1 -mt-1">
                    <span className={`text-[9px] font-bold uppercase tracking-tighter ${(activeSession.scriptContent?.length || 0) > 3800 ? 'text-red-400' : 'text-gray-500'}`}>
                      {activeSession.scriptContent?.length || 0} / 3800
                    </span>
                  </div>
                  <PillButton 
                    variant="filled" 
                    onClick={handleBreakdownScript} 
                    disabled={isProcessingScript || !activeSession.scriptContent || (activeSession.scriptContent?.length || 0) > 3800} 
                    className="w-full h-10" 
                    icon={isProcessingScript ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16} />}
                  >
                    Breakdown
                  </PillButton>
                </div>
              )}
              {activeSession?.useGlobalPrompt && !activeSession?.scriptMode && (
                <textarea value={activeSession.globalPrompt} onChange={(e) => updateActiveSession({ globalPrompt: e.target.value })} placeholder={`E.g. ${randomPlaceholder}`} className="w-full h-24 bg-white/10 rounded-xl p-3 text-[11px] focus:bg-white/10 outline-none transition-colors resize-none mt-1" />
              )}
              <div className="flex flex-col mt-2">
                <SectionLabel>Global References</SectionLabel>
                <div className="flex flex-wrap gap-2 mt-1">
                  {activeSession?.globalRefs.images?.map((ref) => (
                    <div key={ref.id} className="relative group w-12 h-12 rounded-lg overflow-hidden border border-white/10">
                      <img src={"data:" + (ref.mimeType || 'image/png') + ";base64," + ref.base64} className="w-full h-full object-cover" />
                      <button onClick={() => handleClearReference('global-ref', undefined, ref.id)} className="absolute top-0 right-0 p-1 bg-black/60 opacity-0 group-hover:opacity-100"><X size={10} /></button>
                    </div>
                  ))}
                  <button onClick={() => handleSelectReference('global-ref')} className="w-12 h-12 flex items-center justify-center rounded-lg bg-white/10 hover:bg-white/20 border border-dashed border-white/20"><Plus size={14} /></button>
                </div>
              </div>
            </div>
            {!activeSession?.useGlobalPrompt && (
              <div className="flex flex-col gap-4">
                <SectionLabel>Sequence</SectionLabel>
                {activeSession?.cells.slice(0, activeSession.rows * activeSession.cols).map((cell, idx) => (
                  <div key={cell.id} className="p-3 bg-white/5 rounded-2xl flex flex-col gap-3 focus-ring transition-all border border-white/[0.01]">
                    <div className="flex items-center justify-between px-1">
                      <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest font-mono">#{idx + 1}</span>
                      <button onClick={() => handleSelectReference('cell-sketch', cell.id)} className={"text-[8px] font-bold px-2 py-0.5 rounded-lg transition-all " + (cell.sketchBase64 ? 'bg-white text-black shadow-lg' : 'bg-white/10 text-gray-400 hover:text-white/60')}>{cell.sketchBase64 ? 'COMP ✓' : '+ COMPOSITION'}</button>
                    </div>
                    <div className="grid grid-cols-2 gap-1.5">
                      <select value={cell.shotType} onChange={(e) => { const nc = [...activeSession.cells]; nc[idx].shotType = e.target.value; nc[idx].isModified = true; updateActiveSession({ cells: nc }); }} className="bg-white/10 rounded-lg px-2 py-2 text-[10px] outline-none text-gray-300">{SHOT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}</select>
                      <select value={cell.pov} onChange={(e) => { const nc = [...activeSession.cells]; nc[idx].pov = e.target.value; nc[idx].isModified = true; updateActiveSession({ cells: nc }); }} className="bg-white/10 rounded-lg px-2 py-2 text-[10px] outline-none text-gray-300">{POV_ANGLES.map(p => <option key={p} value={p}>{p}</option>)}</select>
                    </div>
                    <PromptTextarea value={cell.prompt} onChange={(val) => { const nc = [...activeSession.cells]; nc[idx].prompt = val; nc[idx].isModified = true; updateActiveSession({ cells: nc }); }} placeholder="Shot details..." className="bg-transparent text-[11px] focus:outline-none border-b border-white/5 pb-1 h-12 resize-none w-full" localRefs={[...(cell.localRefs || []), ...(cell.sketchBase64 ? [{ id: 'sketch', base64: cell.sketchBase64, mimeType: cell.sketchMimeType as string, label: 'sketch', display: 'Sketch' }] : [])]} />
                    {cell.result && (
                      <button disabled={!cell.isModified} onClick={(e) => { e.stopPropagation(); handleRegenerateCell(cell.id, cell.prompt, activeSession.model || 'Nano Banana 2'); }} className="h-8 bg-white/10 hover:bg-white/20 active:scale-95 rounded-lg text-white text-[9px] uppercase font-bold tracking-wider flex items-center justify-center transition-all mt-1 disabled:opacity-30 disabled:pointer-events-none"><Sparkles size={12} className="mr-1" /> Update / Refine Shot</button>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
        <div className="p-4 border-t border-white/5 bg-[#0e0e0e] flex flex-col gap-2">
          {error && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl flex items-start gap-2.5 mb-1 animate-in slide-in-from-bottom-1 duration-200">
              <AlertCircle size={14} className="text-red-400 shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="text-[10px] font-bold text-red-400 leading-tight uppercase tracking-tight">{error}</p>
              </div>
              <button onClick={() => setError(null)} className="text-red-400/50 hover:text-red-400 p-0.5 rounded-md hover:bg-white/5 transition-all">
                <X size={14} />
              </button>
            </div>
          )}
          {(() => {
            const isG = activeSessionId ? generatingStates[activeSessionId]?.isGenerating : false;
            const hasUnexpanded = activeSession && activeSession.cells.slice(0, activeSession.rows * activeSession.cols).some(c => c.result && !c.expandedResult && !c.isRefined);
            const hasAny = activeSession && activeSession.cells.slice(0, activeSession.rows * activeSession.cols).some(c => c.result || c.expandedResult);
            return (
              <>
                <PillButton variant={hasPromptContent ? 'solid' : 'filled'} onClick={handleGenerateGrid} disabled={isG || !activeSession || !hasPromptContent} className="w-full h-11" icon={isG ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16} />}>Generate</PillButton>
                {hasAny && (
                   <button onClick={handleDownloadGrid} disabled={isG} className="w-full h-11 rounded-xl bg-white/5 hover:bg-white/10 text-white font-bold text-[11px] uppercase flex items-center justify-center gap-2 transition-all disabled:opacity-50"><Download size={14} /> Download Full Grid</button>
                )}
                {hasUnexpanded && (
                   <button onClick={handleEnhanceGrid} disabled={isG} className="w-full h-11 rounded-xl bg-white/5 hover:bg-white/10 text-white font-bold text-[11px] uppercase flex items-center justify-center gap-2 transition-all disabled:opacity-50"><Sparkles size={14} /> Enhance All to 1K</button>
                )}
              </>
            );
          })()}
        </div>
      </div>

      <div className="flex-1 h-full flex flex-col items-center justify-center p-8 bg-[#080808] relative">
        {activeSession ? (
          <div className="relative w-full h-full flex flex-col items-center justify-center select-none">
            <div 
              className={`bg-neutral-900 rounded-2xl overflow-hidden ring-1 ring-white/[0.05] shadow-2xl relative grid gap-1.5 p-1.5 transition-all duration-300 max-w-full max-h-full ${activeSessionId && generatingStates[activeSessionId]?.isGenerating ? 'cursor-not-allowed' : ''}`}
              style={{ aspectRatio: String(totalGridRatio), gridTemplateColumns: "repeat(" + activeSession.cols + ", 1fr)", gridTemplateRows: "repeat(" + activeSession.rows + ", 1fr)", width: totalGridRatio >= 1 ? '100%' : 'auto', height: totalGridRatio <= 1 ? '100%' : 'auto' }}
            >
              {activeSession.cells.slice(0, activeSession.rows * activeSession.cols).map((cell, idx) => {
                const displayImg = cell.expandedResult?.base64 || cell.result?.base64;
                const mType = cell.expandedResult?.mimeType || cell.result?.mimeType || 'image/jpeg';
                const isG = activeSessionId ? generatingStates[activeSessionId]?.isGenerating : false;
                const isCRef = generatingStates[cell.id]?.isGenerating || false;
                const isCUps = generatingStates[cell.id + '_upscale']?.isGenerating || false;
                const isCGen = isCRef || isCUps;
                const cStatus = isCRef ? generatingStates[cell.id]?.status : (isCUps ? generatingStates[cell.id + '_upscale']?.status : '');
                const isSel = selectedMulti.includes(idx);
                return (
                  <div key={cell.id} className={`relative group bg-white/[0.01] rounded-lg overflow-hidden border transition-all ${isSel ? 'border-white/80 ring-2 ring-white/30' : 'border-white/[0.03]'} ${(isG || isCGen) ? 'pointer-events-none cursor-not-allowed' : 'cursor-pointer'}`} onClick={(e) => {
                    if (!cell.result || isG || isCGen) return;
                    if (e.shiftKey || e.metaKey || e.ctrlKey) { e.preventDefault(); setSelectedMulti(prev => prev.includes(idx) ? prev.filter(x => x !== idx) : [...prev, idx]); }
                    else { if (selectedMulti.length > 0) { setSelectedMulti([]); setSelectedCellIndex(idx); } else { setSelectedCellIndex(idx); } }
                  }}>
                    {displayImg ? (
                      <>
                        <img src={"data:" + mType + ";base64," + displayImg} className={"w-full h-full object-cover transition-transform duration-700 " + ((isG || isCGen) ? 'opacity-30' : 'group-hover:scale-105')} />
                        {cell.expandedResult && <div className="absolute top-2 left-2 bg-black/60 px-2 py-0.5 rounded-md text-[8px] font-bold text-white uppercase tracking-widest border border-white/10 backdrop-blur-md flex items-center gap-1 z-10"><Sparkles size={8}/> 1K READY</div>}
                      </>
                    ) : <div className="w-full h-full flex flex-col items-center justify-center opacity-10 gap-2 border border-white/5 rounded-md bg-white/[0.01]"><ImageIcon size={28} strokeWidth={1} /><span className="text-[8px] font-bold uppercase tracking-widest text-center px-1 truncate w-full">Shot {(idx + 1)}</span></div>}
                    {cell.result && !isG && !isCGen && <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-2"><Maximize2 size={24} className="text-white/60" /></div>}
                    {isCGen && <div className="absolute inset-0 bg-black/60 animate-pulse flex flex-col items-center justify-center z-10"><Loader2 size={24} className="text-white animate-spin mb-2" /><span className="text-[10px] uppercase font-bold tracking-widest text-white">{cStatus || 'Processing...'}</span></div>}
                  </div>
                );
              })}
            </div>
            {generatingStates[activeSession.id]?.isGenerating && (
              <div className="absolute inset-0 z-50 flex flex-col items-center justify-center bg-[#080808]/80 backdrop-blur-md rounded-2xl">
                 <div className="flex flex-col items-center gap-6 w-72">
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-400 animate-pulse text-center">{generatingStates[activeSession.id].status}</span>
                    <div className="h-[2px] w-full bg-white/5 rounded-full overflow-hidden"><div className="h-full bg-white transition-all duration-700" style={{ width: generatingStates[activeSession.id].progress + "%" }} /></div>
                    <span className="text-3xl font-bold text-white tracking-tighter tabular-nums">{Math.round(generatingStates[activeSession.id].progress)}%</span>
                 </div>
              </div>
            )}
            {activeSession.cells.some(c => c.result) && <div className="absolute -bottom-6 left-1/2 -translate-x-1/2 text-[10px] text-white/30 tracking-widest uppercase">Shift + Click to select multiple</div>}
          </div>
        ) : null}
        <button onClick={() => setIsFeedOpen(!isFeedOpen)} className={"absolute bottom-8 right-8 p-4 rounded-full bg-[#161616] border border-white/5 text-white shadow-2xl transition-all z-40 " + (isFeedOpen ? 'text-white' : 'text-gray-400 hover:text-white/80 hover:bg-white/100')}><History size={24} /></button>
      </div>

      <div className={"h-full border-l border-white/5 bg-[#0a0a0a] flex flex-col shrink-0 transition-all duration-300 " + (isFeedOpen ? 'w-[300px]' : 'w-0 overflow-hidden')}>
        <div className="p-5 border-b border-white/5 flex items-center justify-between"><SectionLabel>History</SectionLabel><button onClick={() => setIsFeedOpen(false)} className="text-gray-400 hover:text-white"><X size={16} /></button></div>
        <div className="flex-1 overflow-y-auto dark-scrollbar p-4 flex flex-col gap-4 min-w-[300px]">
          {sessions.filter(s => s.cells.some(c => c.result) || generatingStates[s.id]?.isGenerating).map(s => (
            <button key={s.id} onClick={() => setActiveSessionId(s.id)} className={"w-full p-4 rounded-2xl border text-left transition-all relative group " + (s.id === activeSessionId ? 'bg-white/5 border-white/[0.05]' : 'bg-transparent border-white/[0.02] hover:border-white/[0.04]')}>
              <div className="flex items-center justify-between mb-3 opacity-30">
                <span className="text-[8px] font-bold uppercase tracking-widest">{s.aspectRatio} | {s.rows}x{s.cols}</span>
                <Trash2 size={12} onClick={(e) => { e.stopPropagation(); setSessions(prev => prev.filter(sess => sess.id !== s.id)); if (activeSessionId === s.id) setActiveSessionId(null); }} className="hover:text-red-500" />
              </div>
              <div className="flex gap-1 h-16 rounded-xl overflow-hidden shadow-2xl grayscale opacity-50 hover:grayscale-0 hover:opacity-100 transition-all duration-700">
                {s.cells.slice(0, 4).map((c, i) => (
                  <div key={i} className="flex-1 bg-white/5 overflow-hidden">
                    {(c.expandedResult?.base64 || c.result?.base64) && <img src={"data:" + (c.expandedResult?.mimeType || c.result?.mimeType || 'image/jpeg') + ";base64," + (c.expandedResult?.base64 || c.result?.base64)} className="w-full h-full object-cover" />}
                  </div>
                ))}
              </div>
            </button>
          ))}
        </div>
      </div>

      {isAddingStyle && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center bg-black/95 backdrop-blur-2xl p-4">
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[40px] w-full max-sm p-10 flex flex-col gap-10 shadow-2xl animate-in zoom-in-95 duration-300">
             <div className="flex items-center justify-between px-2"><SectionLabel>Define Aesthetic</SectionLabel><button onClick={() => setIsAddingStyle(false)} className="p-2 text-gray-500 hover:text-white transition-all"><X size={20} /></button></div>
             <div className="flex flex-col gap-6">
                <div className="flex flex-col gap-2"><span className="text-[9px] font-bold text-gray-500 uppercase tracking-[3px] px-2">Name</span><input value={newStyleName} onChange={(e) => setNewStyleName(e.target.value)} placeholder="e.g. Noir" className="bg-white/5 rounded-2xl px-5 py-4 text-xs outline-none text-white/80" /></div>
                <div className="flex flex-col gap-2"><span className="text-[9px] font-bold text-gray-500 uppercase tracking-[3px] px-2">Logic Rules</span><textarea value={newStylePrompt} onChange={(e) => setNewStylePrompt(e.target.value)} placeholder="Describe lighting..." className="bg-white/5 rounded-2xl px-5 py-5 text-xs h-36 outline-none resize-none text-white/80 leading-relaxed" /></div>
             </div>
             <PillButton variant="solid" onClick={handleAddCustomStyle} className="h-16 rounded-[24px]">Save Aesthetic</PillButton>
          </div>
        </div>
      )}

      {showNewSessionModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center bg-black/80 backdrop-blur-2xl p-4 animate-in fade-in duration-200">
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[40px] w-full max-w-sm p-10 flex flex-col gap-10 shadow-2xl">
             <div className="flex items-center justify-between px-2"><SectionLabel>Start New Grid</SectionLabel><button onClick={() => setShowNewSessionModal(false)} className="p-2 text-gray-500 hover:text-white transition-all"><X size={20} /></button></div>
             <p className="text-gray-400 text-[11px] leading-relaxed px-2">Are you sure you want to start a new grid? Existing work will be lost.</p>
             <div className="flex gap-4"><PillButton variant="outline" className="flex-1 py-5" onClick={() => setShowNewSessionModal(false)}>Cancel</PillButton><PillButton variant="solid" className="flex-1 py-5" onClick={() => createNewSession(true)}>Continue</PillButton></div>
          </div>
        </div>
      )}

      {activeSession && selectedCellIndex !== null && (
        <UpscaleModal cells={activeSession.cells} globalPrompt={activeSession.globalPrompt} useGlobalPrompt={activeSession.useGlobalPrompt} globalRefs={activeSession.globalRefs} initialIndex={selectedCellIndex} aspectRatio={activeSession.layout === '1x4' ? '16:9' : activeSession.aspectRatio} onRegenerateCell={handleRegenerateCell} onSaveExpandedResult={handleSaveExpandedResult} onUpdateCell={(cellId, changes) => { updateActiveSession({ cells: activeSession.cells.map(c => c.id === cellId ? { ...c, ...changes, isModified: true } : c) }); }} onClose={() => setSelectedCellIndex(null)} onUpscaleImage={upscaleImage} generatingStates={generatingStates} />
      )}
    </div>
  );
}

import React from 'react';
import { LayoutGrid } from 'lucide-react';
import { PillButton } from './Common';

export const WelcomeModal = ({ onClose }: { onClose: () => void }) => {
  return (
    <div className="fixed inset-0 z-[600] flex items-center justify-center bg-black/80 backdrop-blur-xl p-4 animate-in fade-in duration-500">
      <div className="bg-[#0a0a0a] border border-white/10 rounded-[40px] w-full max-w-md p-10 flex flex-col gap-8 shadow-2xl animate-in zoom-in-95 duration-500">
        <div className="flex flex-col items-center gap-4 text-center">
          <div className="w-16 h-16 bg-white/5 rounded-3xl flex items-center justify-center shadow-inner border border-white/5">
             <LayoutGrid size={32} className="text-white" />
          </div>
          <h2 className="text-2xl font-bold tracking-tight text-white">Grid Architect</h2>
          <p className="text-sm text-gray-400 leading-relaxed px-2">
            Create perfectly consistent grids of images, automatically separated into individual frames. Refine each shot, adjust camera logic, and upscale to 1K for professional use.
          </p>
        </div>
        <PillButton variant="solid" onClick={onClose} className="h-14 rounded-[24px] font-bold">
          Start Architecting
        </PillButton>
      </div>
    </div>
  );
};
